definition.template:
Sales Qualification =

IF(

    'Opportunity'[Qualification] < 0.5,

    "Low",

    {{condition}} (

        'Opportunity'[Qualification] > 0.7,

        {{high}},

        {{middle}}

    )

)

Measure = {{function}}(
    [Total Sales],
    {{date}}
)

DateTable = Calendar( {{start_function}} (Table1[date],
    [Date]
), {{end_function}} (
    {{combine_function}} (
        SELECTCOLUMNS(Table1, "Date", Table1[date]),
        SELECTCOLUMNS(Table2, "Date", Table2[date])
    ),
    [Date]
))

Sales PYTD =

VAR startyear =
    STARTOFYEAR ( PREVIOUSYEAR ( 'Calendar'[Date] ) )

VAR enddate =
    LASTDATE ( Sales[Date] ) - 365

RETURN

{{fn1}}
    {{fn2}}
        ( Sales[sales] ),
    {{fn3}}
        ( 'Calendar'[Date], startyear, enddate )
)

Sales Previous Year =
{{function_outer}}(
[Total Sales], {{function_date}}(
{{date_column}}
)
)
